// Known-answer tests: the library must reproduce vectors-v1.json (generated by vectors/gen.mjs,
// cross-checked by vectors/xcheck.py) byte for byte.
import { describe, expect, it } from "vitest";
import { blobsDigest, LABEL_INLINE, LABEL_META, type RecordHeader, recordAad, wrapAad } from "../src/aad.js";
import { b64u, fromB64u } from "../src/b64u.js";
import { fromHex, toHex, utf8 } from "../src/bytes.js";
import { canon } from "../src/canon.js";
import { unwrapVmk, wrapVmk } from "../src/envelope.js";
import { CryptoError } from "../src/errors.js";
import { deriveKek, type Kdf } from "../src/kdf.js";
import { metaPadLen, padme, padmeTarget } from "../src/pad.js";
import { selfTest, vectorPassphrase, vectorVaultInfo } from "../src/selftest.js";
import { sha256 } from "../src/suite-sx1.js";
import { unlock, unlockWithKdfFloor } from "../src/vault-info.js";
import { V, vectorRing, withNonces, vectorSecrets } from "./helpers.js";
import { guardOutput } from "./h3.js";

// design §7.2 H3: console output is scanned for the passphrases and VMKs.
guardOutput(vectorSecrets());

const vid = V.inputs.vaultId;
const kdf1000: Kdf = { alg: "PBKDF2-SHA256", iter: 1000, salt: b64u(fromHex(V.inputs.saltHex)) };
const h1 = V.record.header as RecordHeader;
const h2 = V.record2.header as RecordHeader;

describe("inputs", () => {
  it("passphrase is NFD in source and normalizes to the vector NFC bytes", () => {
    const p = vectorPassphrase();
    expect(p).toBe(p.normalize("NFD"));
    expect(toHex(utf8(p.normalize("NFC")))).toBe(V.inputs.passphraseNfcUtf8Hex);
  });
});

describe("KDF and key wrap", () => {
  it("iter 1000: KEK unwraps VMK1 and VMK2; wrap with the vector nonce reproduces the bytes", async () => {
    const kek = await deriveKek(kdf1000, vectorPassphrase());
    expect(toHex(await unwrapVmk(kek, vid, 1, b64u(fromHex(V.inputs.wrapNonceHex)), V.kdf["1000"].wrappedVmk1B64u))).toBe(V.inputs.vmk1Hex);
    expect(toHex(await unwrapVmk(kek, vid, 2, b64u(fromHex(V.inputs.ext.wrapNonce2Hex)), V.kdf["1000"].wrappedVmk2B64u))).toBe(V.inputs.vmk2Hex);
    const w = await withNonces([V.inputs.wrapNonceHex], () => wrapVmk(kek, vid, 1, fromHex(V.inputs.vmk1Hex)));
    expect(w.wrapped).toBe(V.kdf["1000"].wrappedVmk1B64u);
    expect(wrapAad(vid, 1)).toBe(V.kdf["1000"].wrapAad);
  });

  it("iter 600000 (production default) unwraps VMK1", async () => {
    const kek = await deriveKek({ ...kdf1000, iter: 600000 }, vectorPassphrase());
    expect(toHex(await unwrapVmk(kek, vid, 1, b64u(fromHex(V.inputs.wrapNonceHex)), V.kdf["600000"].wrappedVmk1B64u))).toBe(V.inputs.vmk1Hex);
  });

  it("negative: trailing space and wrong-kv AAD fail", async () => {
    const wrong = await deriveKek(kdf1000, vectorPassphrase() + " ");
    await expect(unwrapVmk(wrong, vid, 1, b64u(fromHex(V.inputs.wrapNonceHex)), V.kdf["1000"].wrappedVmk1B64u)).rejects.toThrow();
    const kek = await deriveKek(kdf1000, vectorPassphrase());
    await expect(unwrapVmk(kek, vid, 2, b64u(fromHex(V.inputs.wrapNonceHex)), V.kdf["1000"].wrappedVmk1B64u)).rejects.toThrow();
  });

  it("unlock of the vector vault-info: NFD passphrase ok, trailing space -> WrongPassphrase", async () => {
    const info = vectorVaultInfo("vaultInfo");
    const { ring, cache } = await unlockWithKdfFloor(vectorPassphrase(), info, null, {}, 1000);
    expect(ring.activeKv).toBe(1);
    expect(cache.kvs[1]).toBe(b64u(fromHex(V.inputs.vmk1Hex)));
    await expect(unlockWithKdfFloor(vectorPassphrase() + " ", info, null, {}, 1000)).rejects.toMatchObject({ code: "WrongPassphrase" });
    // Without the test override the iter-1000 vector is below the floor.
    await expect(unlock(vectorPassphrase(), info, null)).rejects.toMatchObject({ code: "UnsupportedKdf" });
  });

  it("unlock of the rotated vault-info yields kv1 and kv2", async () => {
    const { ring } = await unlockWithKdfFloor(vectorPassphrase(), vectorVaultInfo("vaultInfoRotated"), null, {}, 1000);
    expect(ring.kvs).toEqual([1, 2]);
    expect(ring.activeKv).toBe(2);
  });
});

describe("subkeys (checked through their outputs; production subkeys are non-extractable)", () => {
  it("key checks", async () => {
    const r = await vectorRing(true);
    expect(await r.keyCheck(1)).toBe(V.keyCheck.kv1);
    expect(await r.keyCheck(2)).toBe(V.keyCheck.kv2);
    expect(await r.verifyCheck(1, V.keyCheck.kv1)).toBe(true);
    expect(await r.verifyCheck(1, V.keyCheck.kv2)).toBe(false);
  });

  it("gear table: 256 u32 big-endian", async () => {
    const g = await (await vectorRing()).gearTable();
    expect(g.length).toBe(256);
    expect(Array.from(g.subarray(0, 4))).toEqual(V.subkeys.gearFirst4U32BE);
    expect(Array.from(g.subarray(254))).toEqual(V.subkeys.gearLast2U32BE);
    const be = new Uint8Array(1024);
    const dv = new DataView(be.buffer);
    g.forEach((x, i) => dv.setUint32(i * 4, x, false));
    expect(toHex(await sha256(be))).toBe(V.subkeys.gearSha256Hex);
  });
});

describe("identifiers", () => {
  it("pathKey: NFC + lowercase", async () => {
    const r = await vectorRing();
    expect(await r.pathKey(V.ids.path1)).toBe(V.ids.pathKey1);
    expect(await r.pathKey(V.ids.path1.toUpperCase())).toBe(V.ids.pathKey1Upper);
    const p2 = JSON.parse(V.ids.path2JsEscaped) as string;
    expect(p2).not.toBe(p2.normalize("NFC"));
    expect(await r.pathKey(p2)).toBe(V.ids.pathKey2);
    expect(await r.pathKey(p2.normalize("NFC"))).toBe(V.ids.pathKey2);
  });

  it("reserved HMAC fileId (NFD == NFC)", async () => {
    const r = await vectorRing();
    const p2 = JSON.parse(V.ids.path2JsEscaped) as string;
    expect(await r.reservedFileId(V.ids.path1)).toBe(V.ids.reservedFileId1);
    expect(await r.reservedFileId(p2)).toBe(V.ids.reservedFileId2);
    expect(await r.reservedFileId(p2.normalize("NFC"))).toBe(V.ids.reservedFileId2FromNfc);
  });

  it("blobId over the raw chunk", async () => {
    const { blobId, sha256: h } = await (await vectorRing()).blobId(fromHex(V.blob.chunkHex));
    expect(blobId).toBe(V.blob.blobId);
    expect(toHex(h)).toBe(V.blob.chunkSha256Hex);
  });
});

describe("blob envelope", () => {
  it("seal flags 0 and 2 reproduce the vector bytes", async () => {
    const r = await vectorRing();
    const chunk = fromHex(V.blob.chunkHex);
    const n = V.inputs.blobNonceHex;
    const s0 = await withNonces([n], () => r.sealBlob(chunk, V.blob.blobId, { compress: true, pad: false, chunkMax: 4194304 }));
    expect(toHex(s0)).toBe(V.blob.sealedFlags0Hex); // not compressible enough -> flag 0
    const s2 = await withNonces([n], () => r.sealBlob(chunk, V.blob.blobId, { compress: false, pad: true, chunkMax: 4194304 }));
    expect(toHex(s2)).toBe(V.blob.sealedFlags2PadmeHex);
    expect(s2.length - 34).toBe(V.blob.paddedPlainLen);
  });

  it("opens every vector blob, including compressor-dependent flags 1 and 3 and kv2", async () => {
    const r = await vectorRing(true);
    const chunk = fromHex(V.blob.chunkHex);
    expect(toHex(await r.openBlob(fromHex(V.blob.sealedFlags0Hex), V.blob.blobId, chunk.length))).toBe(V.blob.chunkHex);
    expect(toHex(await r.openBlob(fromHex(V.blob.sealedFlags2PadmeHex), V.blob.blobId, chunk.length))).toBe(V.blob.chunkHex);
    const z = utf8(V.blobCompressed.textRepeated.line.repeat(V.blobCompressed.textRepeated.times));
    for (const k of ["sealedFlags1Hex", "sealedFlags3Hex", "sealedKv2Flags0Hex"] as const) {
      expect(toHex(await r.openBlob(fromHex(V.blobCompressed[k]), V.blobCompressed.blobId, z.length))).toBe(toHex(z));
    }
  });

  it("negative vectors", async () => {
    const r = await vectorRing();
    const s = fromHex(V.blob.sealedFlags0Hex);
    const t = s.slice();
    t[t.length - 1]! ^= 1;
    await expect(r.openBlob(t, V.blob.blobId, 49)).rejects.toMatchObject({ code: "BlobIntegrity" });
    await expect(r.openBlob(s, "0".repeat(64), 49)).rejects.toMatchObject({ code: "BlobIntegrity" });
    // kv2 blob without kv2 in the ring
    await expect(r.openBlob(fromHex(V.blobCompressed.sealedKv2Flags0Hex), V.blobCompressed.blobId, V.blobCompressed.chunkLen)).rejects.toMatchObject({ code: "BlobIntegrity" });
  });
});

describe("record meta and inline", () => {
  it("AAD strings and blobsDigest", async () => {
    expect(await recordAad(LABEL_META, vid, h1)).toBe(V.record.metaAad);
    expect(await recordAad(LABEL_INLINE, vid, h1)).toBe(V.record.inlineAad);
    expect(await recordAad(LABEL_META, vid, h2)).toBe(V.record2.metaAad);
    expect(await blobsDigest([])).toBe(V.record.blobsDigestEmpty);
    expect(await blobsDigest(["aa".repeat(32), "bb".repeat(32)])).toBe(V.record.blobsDigestTwo);
    expect(await blobsDigest(h2.blobs)).toBe(V.record2.blobsDigest);
  });

  it("seal meta, inline and padded inline reproduce the vector bytes", async () => {
    const r = await vectorRing();
    const meta = JSON.parse(V.record.metaJson) as Record<string, unknown>;
    expect(await withNonces([V.inputs.metaNonceHex], () => r.sealMeta(meta, h1))).toBe(V.record.metaB64u);
    const body = fromHex(V.record.inlinePlainHex);
    expect(await withNonces([V.inputs.inlineNonceHex], () => r.sealInline(body, h1, { compress: true, pad: false }))).toEqual({ ct: V.record.inlineB64u, z: false, p: false });
    expect(await withNonces([V.inputs.ext.inlineNoncePHex], () => r.sealInline(body, h1, { compress: false, pad: true }))).toEqual({ ct: V.record.inlinePaddedB64u, z: false, p: true });
    const meta2 = JSON.parse(V.record2.metaJson) as Record<string, unknown>;
    expect(await withNonces([V.inputs.ext.meta2NonceHex], () => r.sealMeta(meta2, h2))).toBe(V.record2.metaB64u);
    expect(fromB64u(V.record.metaB64u).length).toBe(12 + V.record.metaPaddedLen + 16);
  });

  it("open, and the meta is self-consistent with the inline body", async () => {
    const r = await vectorRing();
    const m = await r.openMeta(V.record.metaB64u, h1);
    expect(m).toEqual(JSON.parse(V.record.metaJson));
    const body = await r.openInline(V.record.inlineB64u, h1, false, false, m.size as number);
    expect(toHex(await sha256(body))).toBe(m.hash);
    expect(toHex(await r.openInline(V.record.inlinePaddedB64u, h1, false, true, 12))).toBe(V.record.inlinePlainHex);
    expect(await r.openMeta(V.record2.metaB64u, h2)).toEqual(JSON.parse(V.record2.metaJson));
  });

  it("every header mutation in the vectors is rejected", async () => {
    const r = await vectorRing(true);
    const muts: Record<string, Partial<RecordHeader>> = {
      base18010: { base: 18010 }, baseNull: { base: null }, kindDel: { kind: "del" }, rcConfig: { rc: "config" }, kv2: { kv: 2 },
      otherFileId: { fileId: "ffeeddccbbaa99887766554433221100" }, otherPathKey: { pathKey: V.ids.pathKey2 }, oneBlob: { blobs: [V.blob.blobId] },
    };
    for (const [name, m] of Object.entries(muts)) {
      expect((V.record.neg as Record<string, string>)[name]).toBe("rejected");
      await expect(r.openMeta(V.record.metaB64u, { ...h1, ...m }), name).rejects.toMatchObject({ code: "RecordIntegrity" });
    }
  });
});

describe("vault-info and manifest MAC, canonical JSON", () => {
  for (const which of ["vaultInfo", "vaultInfoRotated", "vaultInfoUnknownFields"] as const) {
    it(which, async () => {
      const info = vectorVaultInfo(which);
      const r = await vectorRing(true);
      expect(canon(JSON.parse(V[which].canonical))).toBe(V[which].canonical);
      expect(await r.macVaultInfo(info)).toBe(V[which].infoMac);
      expect(await r.verifyVaultInfo(info)).toBe(true);
      expect(await r.verifyVaultInfo({ ...info, infoRev: info.infoRev + 1 })).toBe(false);
    });
  }

  it("canon built from a fresh object (not the vector string) matches", () => {
    const info = {
      format: "shuttle.vault-info", formatVersion: 1, vaultId: vid, createdAt: 1762318800000, infoRev: 1, epoch: 1,
      kdf: { alg: "PBKDF2-SHA256", iter: 1000, salt: b64u(fromHex(V.inputs.saltHex)) },
      keys: [{ kv: 1, status: "active", suite: "sx1", nonce: b64u(fromHex(V.inputs.wrapNonceHex)), wrapped: V.kdf["1000"].wrappedVmk1B64u, check: V.keyCheck.kv1, createdAt: 1762318800000 }],
      activeKv: 1,
      params: { chunker: { alg: "fastcdc-k1", min: 262144, avg: 1048576, max: 4194304 }, inlineMax: 4096, compression: "deflate-raw", padding: "none", metaPadBucket: 256 },
      retention: { noteDays: 30, attachmentDays: 14, configDays: 30, tombstoneDays: 90, thinAfterHours: 24, thinBucketMinutes: 60 },
      requires: [], unlockRequires: [], features: ["history-v1", "archive-v1"],
    };
    expect(canon(info)).toBe(V.vaultInfo.canonical);
    expect(() => canon({ a: 1.5 })).toThrow();
    expect(() => canon({ a: 2 ** 53 })).toThrow();
    expect(() => canon({ a: undefined })).toThrow();
  });

  it("manifest MAC", async () => {
    const r = await vectorRing();
    const m = JSON.parse(V.manifest.canonical) as Record<string, unknown>;
    expect(await r.macManifest(m)).toBe(V.manifest.mac);
    expect(await r.verifyManifest({ ...m, mac: V.manifest.mac })).toBe(true);
    expect(await r.verifyManifest({ ...m, recordCount: 4, mac: V.manifest.mac })).toBe(false);
    expect(await r.verifyManifest({ ...m, kv: 2, mac: V.manifest.mac })).toBe(false);
    const { kv: _kv, ...noKv } = m;
    expect(await r.verifyManifest({ ...noKv, mac: V.manifest.mac })).toBe(false);
    await expect(r.macManifest(noKv)).rejects.toThrow(/kv/);
  });

  it("manifest written before a rotation still verifies after it (kv in the MAC'd body)", async () => {
    const rotated = await vectorRing(true); // activeKv 2, still holds kv 1
    const m1 = JSON.parse(V.manifest.canonical) as Record<string, unknown>;
    expect(await rotated.verifyManifest({ ...m1, mac: V.manifest.mac })).toBe(true);
    const m2 = JSON.parse(V.manifestKv2.canonical) as Record<string, unknown>;
    expect(await rotated.macManifest(m2)).toBe(V.manifestKv2.mac);
    expect(await rotated.verifyManifest({ ...m2, mac: V.manifestKv2.mac })).toBe(true);
    await expect(rotated.macManifest(m1)).rejects.toThrow(/active kv/);
    // a device that only holds kv 1 cannot verify a kv 2 manifest
    expect(await (await vectorRing()).verifyManifest({ ...m2, mac: V.manifestKv2.mac })).toBe(false);
  });

  it("an own __proto__ key is part of the MAC'd body (canon/without use null-prototype copies)", async () => {
    const r = await vectorRing();
    const info = vectorVaultInfo("vaultInfo");
    const tampered = JSON.parse(JSON.stringify(info).replace(/^\{/, '{"__proto__":"injected",')) as typeof info;
    expect(Object.prototype.hasOwnProperty.call(tampered, "__proto__")).toBe(true);
    expect(await r.verifyVaultInfo(info)).toBe(true);
    expect(await r.verifyVaultInfo(tampered)).toBe(false);
    const m = JSON.parse(V.manifest.canonical.replace(/^\{/, '{"__proto__":{"x":1},')) as Record<string, unknown>;
    expect(await r.verifyManifest({ ...m, mac: V.manifest.mac })).toBe(false);
  });
});

describe("tables", () => {
  it("Padmé and meta buckets", () => {
    for (const [L, t] of Object.entries(V.padme)) expect(padme(Number(L) + 1)).toBe(t);
    for (const [L, t] of Object.entries(V.padmeCapped)) expect(padmeTarget(Number(L), 4194305)).toBe(t);
    for (const [L, t] of Object.entries(V.metaPad)) expect(metaPadLen(Number(L))).toBe(t);
  });
});

describe("runtime self-test", () => {
  it("selfTest('kat') passes", async () => {
    const r = await selfTest("kat");
    expect(r.failures).toEqual([]);
    expect(r.ok).toBe(true);
  });
  it("selfTest('bench') also unwraps the 600k VMK1 vector", async () => {
    const r = await selfTest("bench");
    expect(r.failures).toEqual([]);
    expect(r.ok).toBe(true);
    expect(r.kdfMs).toBeGreaterThan(0);
  }, 60_000);
  it("CryptoError carries the code", () => {
    expect(new CryptoError("Locked").code).toBe("Locked");
  });
});
